import Foundation
import XCTest
@testable import ConjunctionCore

/// testdata/p2p_wire.json (generated by the Python reference, testdata/tools/make_p2p_wire.py).
enum Wire {
    nonisolated(unsafe) static let root: [String: Any] = try! Golden.load("p2p_wire.json")

    static func message(_ name: String) -> [String: Any] { root.list("messages").first { $0.str("name") == name }! }

    static func hello(_ name: String) -> Hello {
        guard case .hello(let h) = try! P2PMessages.decode(unhex(message(name).str("bodyHex"))).message else {
            fatalError("\(name) is not a hello")
        }
        return h
    }

    static func key(_ name: String) -> SoftwareP256Key {
        try! SoftwareP256Key(rawRepresentation: unhex(root.obj("crypto").obj("keys").obj(name).str("d")))
    }
}

func unhex(_ s: String) -> [UInt8] {
    guard let b = P2PBytes.unhex(s) else { fatalError("bad hex \(s)") }
    return b
}

func hexOf(_ b: [UInt8]) -> String { P2PBytes.hex(b) }

final class TestPolicy: LinkPolicy {
    var friendList: [FriendRecord]
    var hidden: Set<String>
    var preset: [String: SwipeDirection]
    let day: LocalDate

    init(friends: [FriendRecord] = [], hidden: Set<String> = [], preset: [String: SwipeDirection] = [:],
         day: LocalDate = LocalDate(2026, 11, 3)) {
        friendList = friends
        self.hidden = hidden
        self.preset = preset
        self.day = day
    }

    func friends() -> [FriendRecord] { friendList }
    func isHidden(_ fingerprint: String) -> Bool { hidden.contains(fingerprint) }
    func presetSwipe(_ fingerprint: String) -> SwipeDirection? { preset[fingerprint] }
    func today() -> LocalDate { day }
}

func profileOf(_ hello: Hello, _ firstName: String, bio: String? = nil, photo: [UInt8]? = nil, eid: String? = nil) -> LocalP2PProfile {
    try! LocalP2PProfile(eid: eid ?? hello.eid, match: hello.match, compat: hello.compat, firstName: firstName, bio: bio,
                         photo: photo, photoW: photo != nil ? 480 : 0, photoH: photo != nil ? 640 : 0)
}

func withMatch(_ p: LocalP2PProfile, _ m: MatchProfile) -> LocalP2PProfile {
    try! LocalP2PProfile(eid: p.eid, match: m, compat: p.compat, firstName: p.firstName, bio: p.bio,
                         photo: p.photo, photoW: p.photoW, photoH: p.photoH)
}

/// Moves frames both ways until quiet, checking frame sizes.
func pump(_ a: P2PLink, _ b: P2PLink, now: Int64 = 1_000,
          tamper: (([UInt8], Bool) -> [UInt8])? = nil, file: StaticString = #filePath, line: UInt = #line) {
    for _ in 0..<10_000 {
        let fa = a.takeFrames()
        let fb = b.takeFrames()
        if fa.isEmpty && fb.isEmpty { return }
        for f in fa {
            XCTAssertLessThanOrEqual(f.count, a.frameLen, file: file, line: line)
            b.onFrame(tamper?(f, true) ?? f, nowMs: now)
        }
        for f in fb {
            XCTAssertLessThanOrEqual(f.count, b.frameLen, file: file, line: line)
            a.onFrame(tamper?(f, false) ?? f, nowMs: now)
        }
    }
    XCTFail("pump did not settle", file: file, line: line)
}

/// Asserts that [body] throws a P2PError with [code].
func expectP2P(_ code: P2PErrorCode, _ message: String = "", file: StaticString = #filePath, line: UInt = #line,
               _ body: () throws -> Void) {
    do {
        try body()
        XCTFail("expected \(code.wire) \(message)", file: file, line: line)
    } catch let e as P2PError {
        XCTAssertEqual(e.code, code, message, file: file, line: line)
    } catch {
        XCTFail("expected P2PError \(code.wire), got \(error) \(message)", file: file, line: line)
    }
}

/// Deterministic generator for fuzz tests (SplitMix64).
struct SeededRNG: RandomNumberGenerator {
    private var state: UInt64
    init(_ seed: UInt64) { state = seed }
    mutating func next() -> UInt64 {
        state &+= 0x9E37_79B9_7F4A_7C15
        var z = state
        z = (z ^ (z >> 30)) &* 0xBF58_476D_1CE4_E5B9
        z = (z ^ (z >> 27)) &* 0x94D0_49BB_1331_11EB
        return z ^ (z >> 31)
    }

    mutating func bytes(_ n: Int) -> [UInt8] { (0..<n).map { _ in UInt8.random(in: 0...255, using: &self) } }
}

extension Array where Element == [UInt8] {
    /// Concatenated payloads (frame header stripped) of one message's frames.
    func joinedBody() -> [UInt8] { flatMap { $0.dropFirst(7) } }
}

extension LinkEvent {
    var name: String {
        switch self {
        case .helloReceived: return "HelloReceived"
        case .noMatch: return "NoMatch"
        case .match: return "Match"
        case .cardReceived: return "CardReceived"
        case .photoReceived: return "PhotoReceived"
        case .peerSwiped: return "PeerSwiped"
        case .friendEstablished: return "FriendEstablished"
        case .friendNearby: return "FriendNearby"
        case .chatReceived: return "ChatReceived"
        case .profileReceived: return "ProfileReceived"
        case .delivered: return "Delivered"
        case .protocolError: return "ProtocolError"
        case .closed: return "Closed"
        }
    }
}

extension [LinkEvent] {
    var protocolErrors: [String] {
        compactMap { if case .protocolError(let code, _, _) = $0 { return code } else { return nil } }
    }

    var friendEstablished: [(peerIdentityKey: [UInt8], friendSecret: [UInt8], safetyCode: String, card: Card?, photo: [UInt8]?)] {
        compactMap {
            if case .friendEstablished(let ik, let fs, let code, let card, let photo, _) = $0 { return (ik, fs, code, card, photo) }
            return nil
        }
    }

    var matches: [P2PMatch] { compactMap { if case .match(let m, _, _) = $0 { return m } else { return nil } } }

    var chats: [ChatPayload] { compactMap { if case .chatReceived(let p) = $0 { return p } else { return nil } } }

    var cards: [Card] { compactMap { if case .cardReceived(let c) = $0 { return c } else { return nil } } }

    var photos: [[UInt8]] { compactMap { if case .photoReceived(let j, _) = $0 { return j } else { return nil } } }

    var friendsNearby: [FriendRecord] { compactMap { if case .friendNearby(let f) = $0 { return f } else { return nil } } }
}
